package battery_status_assessment_service.Battery_Status_Assessment_Service

import org.sireum._
import art._
import battery_status_assessment_service._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait ReportQualification_Api {
  def id: Art.BridgeId
  def captured_report_Id : Art.PortId
  def qualified_evidence_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var qualified_evidence: Battery_Status_Assessment_Service.TaggedQualifiedEvidence = $

  def put_qualified_evidence(value : Battery_Status_Assessment_Service.TaggedQualifiedEvidence) : Unit = {
    Contract(
      Modifies(qualified_evidence),
      Ensures(
        qualified_evidence == value
      )
    )
    Spec {
      qualified_evidence = value
    }

    Art.putValue(qualified_evidence_Id, Battery_Status_Assessment_Service.TaggedQualifiedEvidence_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ReportQualification_Initialization_Api (
  val id: Art.BridgeId,
  val captured_report_Id : Art.PortId,
  val qualified_evidence_Id : Art.PortId) extends ReportQualification_Api

@datatype class ReportQualification_Operational_Api (
  val id: Art.BridgeId,
  val captured_report_Id : Art.PortId,
  val qualified_evidence_Id : Art.PortId) extends ReportQualification_Api {

  // Logika spec var representing port state for incoming data port
  @spec var captured_report: Battery_Status_Assessment_Service.CapturedReport = $

  def get_captured_report() : Option[Battery_Status_Assessment_Service.CapturedReport] = {
    Contract(
      Ensures(
        Res == Some(captured_report)
      )
    )
    val value : Option[Battery_Status_Assessment_Service.CapturedReport] = Art.getValue(captured_report_Id) match {
      case Some(Battery_Status_Assessment_Service.CapturedReport_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port captured_report.  Expecting 'Battery_Status_Assessment_Service.CapturedReport_Payload' but received ${v}")
        None[Battery_Status_Assessment_Service.CapturedReport]()
      case _ => None[Battery_Status_Assessment_Service.CapturedReport]()
    }
    return value
  }
}
